<div class="card"><h2>Historia ya Credit</h2><?php $tq=db()->prepare('SELECT * FROM transactions WHERE user_id=? ORDER BY id DESC LIMIT 30');$tq->execute([$u['id']]);$tx=$tq->fetchAll(); ?><div class="table-wrap"><table><tr><th>Tarehe</th><th>Aina</th><th>Kiasi</th><th>Maelezo</th></tr><?php foreach($tx as $t):?><tr><td><?=e($t['created_at'])?></td><td><?=e($t['type'])?></td><td><?=($t['type']==='credit'?'+':'-').(int)$t['amount']?></td><td><?=e($t['description'])?></td></tr><?php endforeach;?><?php if(!$tx):?><tr><td colspan="4">Hakuna historia bado.</td></tr><?php endif;?></table></div></div>
